import { lazy, Suspense, memo, useMemo, useState } from "react";

const HeavyChart = lazy(() => import("./HeavyChart"));

const Row = memo(function Row({ label }: { label: string }) {
  return <li>{label}</li>;
});

export function BigList({ items }: { items: string[] }) {
  const [q, setQ] = useState("");
  const filtered = useMemo(() => items.filter((x) => x.includes(q)), [items, q]);
  return (
    <>
      <input value={q} onChange={(e) => setQ(e.target.value)} />
      <ul>
        {filtered.map((label) => (
          <Row key={label} label={label} />
        ))}
      </ul>
      <Suspense fallback={<p>График…</p>}>
        <HeavyChart />
      </Suspense>
    </>
  );
}
